SELECT name, version, prev_ms, duration_ms FROM (SELECT c.name, b.version, r.duration_ms, LAG(r.duration_ms) OVER (PARTITION BY r.test_case_id ORDER BY b.built_on) AS prev_ms FROM test_results r JOIN builds b ON b.build_id = r.build_id JOIN test_cases c ON c.test_case_id = r.test_case_id) x WHERE duration_ms > prev_ms;
